def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Extract actions compactly.
    my = [h[0] for h in history]
    op = [h[1] for h in history]
    opD = op.count('D')
    opC = n - opD
    myD = my.count('D')
    last_me = my[-1]
    last_op = op[-1]

    # --- Endgame: secure mutual cooperation, then defect at the very end ---
    remaining = 100 - n
    if remaining <= 0:
        return 'D'

    # If opponent has been almost fully cooperative, quietly exploit at end.
    if opD == 0:
        if remaining <= 1:
            return 'D'
        return 'C'

    # If opponent is fully defecting, stop feeding them.
    if opC == 0:
        return 'D'

    # --- Detect persistent exploiters early ---
    if n >= 6:
        # Opponent defected in the last round and rarely cooperates overall.
        if last_op == 'D' and opD * 2 >= n and n >= 8:
            # One chance to reset if they cooperate next.
            if op[-1] == 'C':
                return 'C'
            return 'D'

    # --- Core: generous tit-for-tat with anti-lock-in and mild forgiveness ---
    if last_op == 'D':
        # If both defected last two rounds, try to break the spiral once.
        if n >= 2 and last_me == 'D' and my[-2] == 'D' and op[-2] == 'D':
            return 'C'
        # If opponent has defected repeatedly, punish hard.
        if n >= 3 and op[-2] == 'D' and op[-3] == 'D':
            return 'D'
        # Otherwise retaliate, but occasionally forgive to restart cooperation.
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    # If we defected last round and opponent still cooperated, they are forgiving;
    # exploit sparingly early/mid game but do not lose them.
    if last_me == 'D':
        if opC >= n - 2 and remaining > 3:
            # They're very forgiving. Occasionally keep taking advantage.
            if rng.random() < 0.35:
                return 'D'
        return 'C'

    # Cooperative streak: build score.
    if opC >= 3 and n >= 3 and op[-1] == 'C' and op[-2] == 'C' and op[-3] == 'C':
        # Slight probing against a long cooperative opponent.
        if remaining > 4 and opD == 0 and n >= 12 and n % 11 == 0:
            return 'D'
        return 'C'

    # Default: cooperate.
    return 'C'
